def conjugate(verb):
    suffixes = {
        'ar': ['o', 'as', 'a', 'amos', 'áis', 'an'],
        'er': ['o', 'es', 'e', 'emos', 'éis', 'en'],
        'ir': ['o', 'es', 'e', 'imos', 'ís', 'en']
    }

    # Find the infinitive suffix
    for suffix in suffixes:
        if verb.endswith(suffix):
            # Remove the infinitive suffix
            stem = verb[:-len(suffix)]
            # Add the personal suffixes
            conjugations = [stem + ending for ending in suffixes[suffix]]
            return {verb: conjugations}

    # If no valid suffix is found, return an empty dictionary
    return {}

